using System.Linq;
using AiLabs.Rules.Config;
using AiLabs.Rules.Core;
using AiLabs.Rules.Sim;
using AiLabs.Rules.State;
using AiLabs.Rules.Systems;
using AiLabs.SimTests.Support;
using Xunit;

namespace AiLabs.SimTests;

/// <summary>Q566–Q665: batch 14 epilogue (grown) — hall/cloud × M&amp;A closure (schema 42).</summary>
public class HatchRivalsChipsEpilogueLaterTests
{
    static ModelState Released(Game g, int cap) => new ModelState
    {
        Id = g.State.TakeId(),
        LineId = "mini",
        Capability = cap,
        Status = ModelStatus.Released,
        Alignment = 500,
        Name = "E"
    };

    static int Hall(Game g, LabState lab)
    {
        int id = g.Do(Command.BuyLand(lab.Id, "us-oregon")).CreatedId;
        lab.Holding(id).HallKw = 450_000;
        return id;
    }

    static void DistressAcquire(Game g, LabState rival)
    {
        if (rival.Models.Count == 0 || rival.Models.All(m => m.Capability < 500))
            rival.Models.Add(Released(g, 510));
        rival.Cash = -17_000;
        rival.WeeksInDebt = 1;
        Finance.Earn(g.Me, LedgerLine.CapitalIn, 95_000_000);
        g.Do(Command.AcquireLab(g.Id, rival.Id));
    }

    [Fact] public void Q566_epilogue_hall_cloud_remap() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4500, 15)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 90_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 100_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); int hall = Hall(g, r); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, hall, 1)); DistressAcquire(g, r); Assert.Equal(2, g.Me.ChipOrders.Count); Assert.Contains(g.Me.ChipOrders, o => o.HoldingId == HardwareBatch.Cloud); }
    [Fact] public void Q567_epilogue_cloud_before_hall() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4200, 12)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 80_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 92_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 2)); int hall = Hall(g, r); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, hall, 1)); DistressAcquire(g, r); Assert.Equal(3, g.Me.ChipOrders.Sum(o => o.Count)); }
    [Fact] public void Q568_hall_holding_persists() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4400, 10)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 70_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 88_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); int hall = Hall(g, r); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, hall, 1)); DistressAcquire(g, r); Assert.Contains(g.Me.Holdings, h => h.HallKw > 0); }
    [Fact] public void Q569_buyer_id_player_hall_order() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4400, 10)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 70_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 88_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); int hall = Hall(g, r); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, hall, 1)); DistressAcquire(g, r); Assert.All(g.Me.ChipOrders, o => Assert.Equal(g.Id, o.BuyerLabId)); }
    [Fact] public void Q570_design_lab_player_hall() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4400, 10)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 70_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 88_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); int hall = Hall(g, r); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, hall, 1)); DistressAcquire(g, r); Assert.All(g.Me.ChipOrders, o => Assert.Equal(g.Id, o.DesignLabId)); }
    [Fact] public void Q571_booked_in_stable() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4000, 8)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 40_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 52_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); string node = r.ChipOrders[0].NodeId; int month = r.ChipOrders[0].FoundryMonth; long booked = ChipQueries.BookedIn(g.State, node, month); DistressAcquire(g, r); Assert.Equal(booked, ChipQueries.BookedIn(g.State, node, month)); }
    [Fact] public void Q572_deliver_hall_order() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4800, 6)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 50_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 60_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); int hall = Hall(g, r); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, hall, 1)); DistressAcquire(g, r); var ho = g.Me.ChipOrders.First(o => o.HoldingId != HardwareBatch.Cloud); g.State.Tick = ho.DeliveryTick; ChipSystem.RunWeek(g.C, g.State, g.Me); Assert.DoesNotContain(g.Me.ChipOrders, o => o.Id == ho.Id); }
    [Fact] public void Q573_holdings_count_acquire() { var g = Game.New(seed: 1187); var r = g.Rival("openaye"); r.Models.Add(Released(g, 532)); r.Cash = -17_300; Finance.Earn(r, LedgerLine.CapitalIn, 8_000_000); int hall = Hall(g, r); Finance.Earn(g.Me, LedgerLine.CapitalIn, 90_000_000); int h0 = g.Me.Holdings.Count; g.Do(Command.AcquireLab(g.Id, r.Id)); Assert.True(g.Me.Holdings.Count > h0); Assert.Contains(g.Me.Holdings, h => h.HallKw == 450_000); }
    [Fact] public void Q574_fire_refused_absorbed() { var g = Game.New(seed: 1188); var r = g.Rival("openaye"); r.Models.Add(Released(g, 520)); r.Cash = -16_800; r.Staff.Add(new StaffMember { Id = g.State.TakeId(), RoleId = "engineer", Morale = 500 }); Finance.Earn(g.Me, LedgerLine.CapitalIn, 70_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); g.Refused(Command.Fire(r.Id, "engineer", 1), CommandError.LabAbsorbed); }
    [Fact] public void Q575_start_training_refused() { var g = Game.New(seed: 1189); var r = g.Rival("openaye"); r.Models.Add(Released(g, 518)); r.Cash = -17_000; Finance.Earn(g.Me, LedgerLine.CapitalIn, 73_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); g.Refused(Command.StartTraining(r.Id, "mini", 0), CommandError.LabAbsorbed); }
