    [Fact] public void Q577_epilogue_save_hall_orders_577() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4100, 10)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 75_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 85_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); _ = Hall(g, r); DistressAcquire(g, r); var l = new Game(Simulation.Load(g.C, g.Sim.Save())); Assert.Equal(g.Me.ChipOrders.Count, l.Me.ChipOrders.Count); SaveSchemaPretend.AssertRoundTrip(l.Sim); }
    [Fact] public void Q578_epilogue_triple_buyer_global_578() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 3800, 20)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 120_000_000); LabState o = HatchFollowUpLaterTests.OpenAyeBuyer(g, 100_000_000); LabState a = WorldSetup.AddRival(g.C, g.State, g.C.Rival("anthoptics"), EraSystem.AtTick(g.C, g.Tick), true); Finance.Earn(a, LedgerLine.CapitalIn, 90_000_000); g.Do(Command.BuyListedChips(o.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); g.Do(Command.BuyListedChips(a.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); int g0 = g.State.Labs.Sum(l => l.ChipOrders.Count); DistressAcquire(g, o); Assert.Equal(g0 - 1 + g.Me.ChipOrders.Count, g.State.Labs.Sum(l => l.ChipOrders.Count)); }
    [Fact] public void Q579_epilogue_crash_own_order_579() { var g = Game.New(seed: 1204); g.State.BubbleCrashMonthsRemaining = 5; var r = g.Rival("openaye"); r.Models.Add(Released(g, 480)); r.Cash = -28_000; r.WeeksInDebt = 2; int did = g.State.TakeId(); r.ChipDesigns.Add(new ChipDesign { Id = did, Status = ChipDesignStatus.Ready, NodeId = "n28", DieId = "medium", FormatId = "fp16", MemoryId = "ddr", CoolingId = "air", Target = "inference", Version = 1, YieldPermille = 760 }); int month = ChipQueries.MonthIndex(g.C, g.State.Tick); r.ChipOrders.Add(new ChipOrder { Id = g.State.TakeId(), DesignId = did, BuyerLabId = r.Id, DesignLabId = r.Id, HoldingId = HardwareBatch.Cloud, Count = 2, FoundryMonth = month, DeliveryTick = g.State.Tick + 24, NodeId = "n28" }); Finance.Earn(g.Me, LedgerLine.CapitalIn, 150_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); Assert.Single(g.Me.ChipOrders); }
