    [Fact] public void Q582_epilogue_chip_sales_third_party_582() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4600, 6)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 32_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 44_000_000); long s0 = g.Me.Ledger.Lifetime.ChipSales; g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); DistressAcquire(g, r); LabState a = WorldSetup.AddRival(g.C, g.State, g.C.Rival("anthoptics"), EraSystem.AtTick(g.C, g.Tick), true); Finance.Earn(a, LedgerLine.CapitalIn, 30_000_000); g.Do(Command.BuyListedChips(a.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Assert.True(g.Me.Ledger.Lifetime.ChipSales > s0); }
